-- GENERATED by tools/gen_state_mod.py from templates/state_names and data/states/us_colorado; edit those, not this file.
-- Game script of "square_names_us_colorado": gives NEW player-built stops and passenger stations in known cities real names
-- (cities.lua). Pattern proven by mods/square_town_street_names_probe (docs/findings.md "Street names and Road
-- Stops"):
--   handleEvent  onPostBuildProposal (player builds only): queue the new station ids in `state`. No commands
--                here (memory gs-no-sendcommand-in-build-events); build events and update run in separate Lua
--                states, so `state` is the only channel.
--   update       subscribes lazily (never in the map editor); about a second after a build, renames each queued
--                station's group with makeEntitySetNameCmd WITHOUT a callback ("Callbacks are currently
--                disallowed" in the engine update), then drops them from the queue.
-- Never touches existing stations (stops a proposal only re-creates, e.g. on a road upgrade, are skipped), skips
-- groups the player renamed or that hold stations from older builds, and names already in use (also names sent
-- but not yet applied). A queue saved mid-delay is finished after load with the same checks. Phase 2 cases:
-- tests/<modId>/test_rename.lua (second half). A city name shared with a bigger city of another active series mod
-- (data/contested.lua) is left to that mod unless the game uses this mod's name set. Every entry point in pcall,
-- each distinct error logged once. Plain Lua, pre-5.3; exports via data() (memory script-lua-exports-via-data).

local MOD_ID = "square_names_us_colorado"
local TAG = "[" .. MOD_ID .. "] "
local STATE_V = 1
local QUEUE_CAP = 64
local DELAY_SECONDS = 1   -- let the engine finish naming the new group first
local EV_POST = "onPostBuildProposal"

local warned = {}
local function log(msg)
	pcall(print, TAG .. msg)
end
local function warnOnce(key, msg)
	if warned[key] then return end
	warned[key] = true
	log("ERROR " .. msg)
end

local function req(file)
	return require(MOD_ID .. "::/" .. MOD_ID .. "/" .. file)
end

local function try(fn, ...)
	local ok, a = pcall(fn, ...)
	if ok then return a end
	return nil
end

---------------------------------------------------------------------------
-- Engine reads

local function ct()
	return api.type.ComponentType
end

local function getComp(e, t)
	if type(e) ~= "number" or e < 0 then return nil end
	return try(function() return api.engine.getComponent(e, t) end)
end

local function exists(e)
	if type(e) ~= "number" or e < 0 then return false end
	return try(api.engine.entityExists, e) == true
end

local function entityName(e)
	local n = try(api.engine.util.getEntityName, e)
	if type(n) == "string" then return n end
	local c = getComp(e, ct().NAME)
	return c and try(function() return c.name end) or nil
end

local function groupOf(st)
	return try(api.engine.system.stationGroupSystem.getStationGroup, st)
end

local function groupStations(g)
	local sg = getComp(g, ct().STATION_GROUP)
	if sg == nil then return {} end
	return try(function()
		local out = {}
		for _, s in ipairs(sg.stations or {}) do out[#out + 1] = s end
		return out
	end) or {}
end

--- false when every readable terminal is cargo-only; true when any is passenger or none can be read.
local function isPassenger(st)
	local comp = getComp(st, ct().STATION)
	if comp == nil then return true end
	local seen, pax = false, false
	pcall(function()
		for _, term in ipairs(comp.terminals or {}) do
			seen = true
			if term.passengersLoad or term.passengersUnload then pax = true end
		end
	end)
	return pax or not seen
end

local function modParams()
	return try(api.engine.config.getModParams) or {}
end

local function isMapEditor()
	local p = modParams()[""]
	return type(p) == "table" and p.isMapEditor == true
end

---------------------------------------------------------------------------
-- State (small: only the pending queue)

local function getState(state)
	local s = state:get()
	if type(s) ~= "table" or s.v ~= STATE_V then return { v = STATE_V, q = {}, b = 0 } end
	if type(s.q) ~= "table" then s.q = {} end
	return s
end

---------------------------------------------------------------------------
-- Build event: collect new stations

-- Edge objects of a proposal get placeholder ids from PLACEHOLDER_BASE, in edgeObjectsToAdd order
-- (base/content/game_mechanics/towns/town_util.tl getProposalActions).
local PLACEHOLDER_BASE = -400000000

local function nonEmpty(v)
	if v == nil then return false end
	local n = try(function() return #v end)
	return n == nil or n > 0
end

--- The proposal's edge object maps, read once per build (each field access converts the whole engine map):
--- new2oldEdgeObjects as is, and the ids old2newEdgeObjects names as new forms of old objects, as a set.
local function edgeObjectMaps(sp)
	local n2o = try(function() return sp.new2oldEdgeObjects end)
	local renewed = {}
	pcall(function()
		for _, news in pairs(sp.old2newEdgeObjects or {}) do
			for _, n in ipairs(news) do renewed[n] = true end
		end
	end)
	return n2o, renewed
end

--- true when edge object #i (result id `id`) is an existing object the proposal re-creates (road upgrade,
--- edge split by a neighbouring build) rather than a new stop: new2oldEdgeObjects maps it to old objects
--- (the test base town_util.tl uses), or old2newEdgeObjects names it as the new form of an old object.
local function carriedOver(n2o, renewed, i, id)
	if n2o ~= nil then
		if nonEmpty(try(function() return n2o[PLACEHOLDER_BASE + i - 1] end)) then return true end
		if nonEmpty(try(function() return n2o[id] end)) then return true end
	end
	return renewed[id] == true
end

--- Number of constructions the proposal adds; nil when unreadable (then the result entities are scanned).
local function addedConstructions(proposal)
	local n = try(function() return proposal.toAdd_native:size() end)
	if type(n) == "number" then return n end
	return try(function() return #proposal.toAdd end)
end

local function collect(p)
	local proposal = p[1]
	local found = {}
	-- Road Stops (one- and two-sided): edge objects with category 0 carry the real station id after the build.
	pcall(function()
		local sp = proposal.proposal
		local n2o, renewed
		for i, eo in ipairs(sp.edgeObjectsToAdd or {}) do
			local id = eo.resultEntity
			if eo.category == 0 and type(id) == "number" and id >= 0 then
				if n2o == nil and renewed == nil then n2o, renewed = edgeObjectMaps(sp) end
				if not carriedOver(n2o, renewed, i, id) then found[#found + 1] = { st = id, k = "stop" } end
			end
		end
	end)
	-- Station constructions: only brand-new ones (an upgrade or rebuild removes the old construction). A
	-- proposal without constructions (tracks, roads, Road Stops) skips the result scan: one getComponent per
	-- new edge and node otherwise.
	local removes = try(function() return #(proposal.toRemove or {}) end) or 0
	if removes == 0 and addedConstructions(proposal) ~= 0 then
		local logic = req("sn_logic.lua")
		for _, e in ipairs(p[3] or {}) do
			if type(e) == "number" and e >= 0 then
				local con = getComp(e, ct().CONSTRUCTION)
				local kind = con and logic.kindOfFile(try(function() return con.fileName end)) or nil
				if kind then
					pcall(function()
						for _, st in ipairs(con.stations or {}) do found[#found + 1] = { st = st, k = kind } end
					end)
				end
			end
		end
	end
	return found
end

local function doHandleEvent(state, id, name, param)
	if id ~= "apply_command" or name ~= EV_POST then return end
	if type(param) ~= "table" or param[1] == nil or param[4] ~= true then return end
	local found = collect(param)
	if #found == 0 then return end
	if isMapEditor() then return end   -- after collect: getModParams copies every mod's params
	local s = getState(state)
	s.b = (tonumber(s.b) or 0) + 1
	local now = os.time()
	local queued = {}
	for _, e in ipairs(s.q) do queued[e.st] = true end
	for _, f in ipairs(found) do
		if #s.q >= QUEUE_CAP then break end
		if not queued[f.st] then
			queued[f.st] = true
			local g = groupOf(f.st)
			local n = g and entityName(g) or nil
			-- Only plain numbers and strings go into the saved state.
			if type(n) ~= "string" then n = nil end
			if type(g) ~= "number" then g = -1 end
			s.q[#s.q + 1] = { st = f.st, k = f.k, g = g, n = n, b = s.b, t = now }
		end
	end
	state:set(s)
end

---------------------------------------------------------------------------
-- Update: rename

-- Names this Lua state sent recently (group -> { n = name, t = time }). sendCommand without a callback is
-- applied later, so until the group shows the name, it still counts as in use: two passes in quick succession
-- never pick the same street. Session-only, never saved.
local sentNames = {}
local SENT_TTL = 30

local function pruneSent(now)
	for g, v in pairs(sentNames) do
		if not exists(g) or entityName(g) == v.n or now - v.t > SENT_TTL or now < v.t then sentNames[g] = nil end
	end
end

local function namesOfGroups(groups, skip)
	local out, seen = {}, {}
	for _, g in ipairs(groups) do
		if g ~= skip and not seen[g] then
			seen[g] = true
			local n = entityName(g)
			if n then out[#out + 1] = n end
			if sentNames[g] then out[#out + 1] = sentNames[g].n end
		end
	end
	return out
end

local function townGroups(town)
	-- getStations(town) returns one town's list; getTown2StationsMap builds the whole map (fallback only).
	local sts = try(api.engine.system.stationSystem.getStations, town)
		or try(function() return api.engine.system.stationSystem.getTown2StationsMap()[town] end) or {}
	local groups = {}
	for _, st in ipairs(sts) do
		local g = groupOf(st)
		if g and g >= 0 then groups[#groups + 1] = g end
	end
	return groups
end

local function allGroups()
	return try(api.engine.getEntitiesWithComponent, ct().STATION_GROUP) or {}
end

--- Renames the `due` entries. `fresh` holds every station still queued (due or not): a group whose stations
--- are all in it was made by these builds; any other member means it joined an existing group.
--- Returns the number of commands sent.
local function processQueue(due, fresh)
	local logic = req("sn_logic.lua")
	local cities = req("data/cities.lua")
	local stateData = req("data/state.lua")
	local contested = try(req, "data/contested.lua")
	local allParams = modParams()
	local params = allParams[MOD_ID] or {}
	local streetsOn = logic.paramOn(params.streetNames)
	local stationsOn = logic.paramOn(params.stationNames)
	local cfg = try(api.engine.config.getConfigDict)
	local nameList = cfg and try(function() return cfg.nameList end) or nil
	if not logic.isActive(nameList, MOD_ID) then return 0 end

	local now = os.time()
	pruneSent(now)
	local done, townUsed, globalUsed, sent = {}, {}, nil, 0
	for _, e in ipairs(due) do
		local ok, err = pcall(function()
			if not exists(e.st) then return end                                -- bulldozed since the build
			local wantStop = e.k == "stop"
			if (wantStop and not streetsOn) or (not wantStop and not stationsOn) then return end
			local g = groupOf(e.st)
			if g == nil or g < 0 or done[g] then return end
			if e.g ~= nil and e.g >= 0 and g ~= e.g then return end            -- moved to another group
			local cur = entityName(g)
			if e.n ~= nil and e.n ~= "" and cur ~= e.n then return end         -- renamed since the build
			for _, m in ipairs(groupStations(g)) do
				if not fresh[m] then return end                                -- joined an existing group
			end
			if not isPassenger(e.st) then return end
			local town = try(api.engine.system.stationSystem.getTown, e.st)
			if type(town) ~= "number" or town < 0 or not exists(town) then return end
			local townName = entityName(town)                               -- the town's current name
			local city = logic.findCity(cities, townName)
			if city == nil then return end
			if not logic.cityAllowed(contested, townName, MOD_ID, allParams, nameList) then return end  -- G9
			local name
			if wantStop then
				local used = townUsed[town]
				if used == nil then
					used = logic.newUsed(namesOfGroups(townGroups(town), g))
					townUsed[town] = used
				end
				name = logic.pickStreet(city.streets, used)
			else
				if globalUsed == nil then globalUsed = logic.newUsed(namesOfGroups(allGroups(), g)) end
				local base = logic.pickStation(logic.stationList(city, e.k), globalUsed)
				name = logic.stationName(e.k, base, stateData.stationSuffix)
			end
			done[g] = true
			if name == nil then return end
			-- Names given in this pass are in use for the rest of it (also when the default already fits).
			if globalUsed then logic.addUsed(globalUsed, name) end
			for _, u in pairs(townUsed) do logic.addUsed(u, name) end
			if name == cur then return end
			api.cmd.sendCommand(api.cmd.makeEntitySetNameCmd(g, name))
			sentNames[g] = { n = name, t = now }
			sent = sent + 1
			log(string.format("renamed %s group %d (%s) -> %s", e.k, g, tostring(cur), name))
		end)
		if not ok then warnOnce("rename:" .. tostring(err), "rename failed: " .. tostring(err)) end
	end
	return sent
end

local lastPoll = nil   -- os.time() of the last queue check in this Lua state

local function doUpdate(state)
	if not state:hasEventSubscriptions() then
		-- Never in the map editor: without subscriptions no build event reaches us, and a queue is never run.
		if isMapEditor() then return end
		-- Lazy: lifecycle events don't reach a mod added to an existing save.
		state:subscribeToNoEvents()
		state:subscribeToEvent(EV_POST)
	end
	-- Entries become due only when os.time() ticks over, so read the state once per second, not every frame.
	local now = os.time()
	if now == lastPoll then return end
	lastPoll = now
	local s = state:get()
	if type(s) ~= "table" or type(s.q) ~= "table" or #s.q == 0 then return end
	-- Entries at least DELAY_SECONDS old are due (the engine has named their groups); younger ones wait for a
	-- later update. A queue loaded from a save is due at once (its builds are done). Bad entries are dropped.
	local due, keep, fresh = {}, {}, {}
	for _, e in ipairs(s.q) do
		if type(e) == "table" and type(e.st) == "number" then
			fresh[e.st] = true
			local age = now - (tonumber(e.t) or 0)
			if age >= 0 and age < DELAY_SECONDS then keep[#keep + 1] = e else due[#due + 1] = e end
		end
	end
	if #due == 0 and #keep == #s.q then return end
	-- Drop the due entries even if renaming fails, so a bad entry never sticks in the save.
	state:set({ v = STATE_V, q = keep, b = s.b })
	if #due == 0 then return end
	local ok, err = pcall(processQueue, due, fresh)
	if not ok then warnOnce("process:" .. tostring(err), "rename pass failed: " .. tostring(err)) end
end

function data()
	return {
		update = function(_userParams, state, _dt)
			local ok, err = pcall(doUpdate, state)
			if not ok then warnOnce("update:" .. tostring(err), "update failed: " .. tostring(err)) end
		end,
		handleEvent = function(_userParams, state, _src, id, name, param)
			local ok, err = pcall(doHandleEvent, state, id, name, param)
			if not ok then warnOnce("event:" .. tostring(err), "handleEvent " .. tostring(name) .. " failed: " .. tostring(err)) end
		end,
	}
end
